	}
}

func TestFillRequiresHeadEnd(t *testing.T) {
	if _, err := fill("<html><body></body></html>", sources{record: &record{}, git: fakeGit{}}); err == nil {
		t.Error("</head> が無いのにエラーにならなかった")
	}
